milestones.milestoneCriteriaFormula:
OR(AND(
        ISPICKVAL(Type, 'Standard'), 
        OR(
                Routing_Issue_Type__c == 'Non-Technical', 
                Routing_Issue_Type__c == 'Technical'
        ),
        ISPICKVAL(Contact.Active_services__c, 'Essential'), 
        OR(
                NOT(Contact.X24_7_Hand_off_Contact__c), 
                Contact.US_Support_required__c
        )
), 

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)

OR(AND(
        ISPICKVAL(Type, 'Standard'), 
        OR(
                Routing_Issue_Type__c == 'Non-Technical', 
                Routing_Issue_Type__c == 'Technical'
        ),
        ISPICKVAL(Contact.Active_services__c, 'Essential'), 
        Contact.X24_7_Hand_off_Contact__c, 
        NOT(Contact.US_Support_required__c)
), 

(AND(ISPICKVAL(Type, 'Escalation'),OR(Owner:Queue.QueueName =='SRE Escalations',Owner:User.UserRole.Name=='SRE Engineers')
)
)
)
